import { Button, Component, director, instantiate, Label, Node, Prefab, sp } from 'cc';
import AppAssetBundle from '../utils/AppAssetBundle';
import { GameViewAdapter } from './GameViewAdapter';
import { JackpotView } from './JackpotView';
import { WinAnimationView } from './WinAnimationView';
import StoreManager from '../store/StoreManager';
import GameConfigManager from '../config/GameConfigManager';

interface DismissableView {
    dismissExternal(): void;
    onDismissing: (() => void) | null;
}

function snapshotLayers(node: Node, snap: Map<Node, number>): void {
    snap.set(node, node.layer);
    const cs = node.children;
    for (let i = 0; i < cs.length; i++) snapshotLayers(cs[i], snap);
}
function restoreLayers(snap: Map<Node, number>): void {
    for (const [n, layer] of snap) n.layer = layer;
}

interface LoadOptions<T> {
    pathOf: (v: GameViewAdapter) => string;
    defaultPath: string;
    onLoaded: (node: Node, v: GameViewAdapter) => T;
}

/**
 * 集中管理 3 個動態載入的彈窗
 * winAnimation 是單一全螢幕實例 其餘彈窗維持 per-view 實例
 * per-view pattern：cache promise → loop allViews → loadPrefab → instantiate
 *   → 暫掛 popupRoot 取世界座標 → reparent 到 sceneRoot → siblingIndex 999 → active=false
 */
export class GamePopupManager {
    constructor(
        private host: Component,
        private getViews: () => GameViewAdapter[]
    ) {}

    private winAnimationViewInstance: WinAnimationView | null = null;
    jackpotViews: JackpotView[] = [];
    buyFeaturePopups: Node[] = [];
    buyFeatureMasks: Node[] = [];
    buyFeatureSpines: sp.Skeleton[] = [];
    buyFeatureConfirmBtns: Button[] = [];
    buyFeatureCancelBtns: Button[] = [];
    buyFeatureAmountLabels: Label[] = [];

    get winAnimationView(): WinAnimationView | null {
        return this.winAnimationViewInstance;
    }
    get jackpotView(): JackpotView | null {
        return this.jackpotViews[0] ?? null;
    }
    get buyFeaturePopup(): Node | null {
        return this.buyFeaturePopups[0] ?? null;
    }
    get buyFeatureAmountLabel(): Label | null {
        return this.buyFeatureAmountLabels[0] ?? null;
    }

    private async loadForAllViews<T>(opts: LoadOptions<T>): Promise<T[]> {
        const sceneRoot = director.getScene()?.getChildByName('Canvas');
        const prefabCache: Record<string, Prefab> = {};
        const results: T[] = [];
        for (const v of this.getViews()) {
            const path = opts.pathOf(v) || opts.defaultPath;
            if (!prefabCache[path]) prefabCache[path] = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(path);
            const node = instantiate(prefabCache[path]);
            // 先快照 prefab 原始 layer（粒子等可能用 DEFAULT，不能一律改成 UI_2D）
            const layerSnap = new Map<Node, number>();
            snapshotLayers(node, layerSnap);

            const initialParent = v.popupRoot ?? this.host.node;
            initialParent.addChild(node);
            if (sceneRoot && sceneRoot !== initialParent) {
                const worldPos = node.worldPosition.clone();
                sceneRoot.addChild(node);
                node.setWorldPosition(worldPos);
                // 暫掛在 viewH/viewV 時被 CHILD_ADDED 染上 VIEW_H/V layer，搬到 sceneRoot 後還原為 prefab 原 layer
                restoreLayers(layerSnap);
            }
            node.setSiblingIndex(999);
            node.active = false;
            results.push(opts.onLoaded(node, v));
        }
        return results;
    }

    /** 報獎只建立一個實例 還是由 GameViewAdapter 微調 */
    private async loadWinAnimation(): Promise<WinAnimationView> {
        const views = this.getViews();
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const adapter = views.find((view) => view.node.name === adapterName) ?? views[0];
        const path = adapter?.winAnimationPrefabPath || 'resources/prefabs/winAnimationView';
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(path);
        const node = instantiate(prefab);
        const sceneRoot = director.getScene()?.getChildByName('Canvas') ?? this.host.node;
        sceneRoot.addChild(node);
        node.setSiblingIndex(999);
        node.active = false;
        return node.getComponent(WinAnimationView)!;
    }

    private _winAnimPromise: Promise<WinAnimationView> | null = null;
    async getWinAnimation(): Promise<WinAnimationView> {
        if (this.winAnimationViewInstance) return this.winAnimationViewInstance;
        if (!this._winAnimPromise) {
            this._winAnimPromise = (async () => {
                const t0 = performance.now();
                console.log(`[Popup] winAnimationView: start loading`);
                const view = await this.loadWinAnimation();
                this.winAnimationViewInstance = view;
                console.log(`[Popup] winAnimationView: ready ${(performance.now() - t0).toFixed(0)}ms`);
                return view;
            })();
        }
        return this._winAnimPromise;
    }

    private _jackpotPromise: Promise<JackpotView> | null = null;
    async getJackpot(): Promise<JackpotView> {
        if (this.jackpotViews.length) return this.jackpotViews[0];
        if (!this._jackpotPromise) {
            this._jackpotPromise = (async () => {
                const t0 = performance.now();
                console.log(`[Popup] jackpotView: start loading`);
                await this.loadForAllViews({
                    pathOf: (v) => v.jackpotPrefabPath,
                    defaultPath: 'resources/prefabs/JackpotView',
                    onLoaded: (node, v) => {
                        const jv = node.getComponent(JackpotView)!;
                        const lp = v.jackpotBgSpineLpos;
                        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) jv.bgSpine.node.setPosition(lp);
                        const sc = v.jackpotBgSpineScale;
                        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) jv.bgSpine.node.setScale(sc);
                        this.jackpotViews.push(jv);
                        return jv;
                    },
                });
                console.log(`[Popup] jackpotView: ready ${(performance.now() - t0).toFixed(0)}ms`);
                return this.jackpotViews[0];
            })();
        }
        return this._jackpotPromise;
    }

    private _buyFeaturePromise: Promise<void> | null = null;
    async getBuyFeature(onConfirm: (e?: unknown) => void, onCancel: (e?: unknown) => void, thisArg: unknown): Promise<void> {
        if (this.buyFeaturePopups.length) return;
        if (!this._buyFeaturePromise) {
            this._buyFeaturePromise = (async () => {
                const t0 = performance.now();
                console.log(`[Popup] buyFeaturePopup: start loading`);
                await this.loadForAllViews({
                    pathOf: (v) => v.buyFeaturePrefabPath,
                    defaultPath: 'resources/prefabs/buyFeaturePopup',
                    onLoaded: (node, _v) => {
                        this.buyFeaturePopups.push(node);
                        const mask = (node.getChildByName('featureBg') ?? node.getChildByName('bg'))!;
                        this.buyFeatureMasks.push(mask);
                        this.buyFeatureSpines.push(node.getComponentInChildren(sp.Skeleton)!);
                        let okBtn: Button | null = null;
                        let closeBtn: Button | null = null;
                        for (const btn of node.getComponentsInChildren(Button)) {
                            if (btn.node.name === 'OK') okBtn = btn;
                            if (btn.node.name === 'CLOSE') closeBtn = btn;
                        }
                        this.buyFeatureConfirmBtns.push(okBtn!);
                        this.buyFeatureCancelBtns.push(closeBtn!);
                        this.buyFeatureAmountLabels.push(node.getComponentInChildren(Label)!);
                        okBtn?.node.on(Button.EventType.CLICK, onConfirm, thisArg);
                        closeBtn?.node.on(Button.EventType.CLICK, onCancel, thisArg);
                        mask?.on(Node.EventType.TOUCH_END, onCancel, thisArg);
                        return node;
                    },
                });
                console.log(`[Popup] buyFeaturePopup: ready ${(performance.now() - t0).toFixed(0)}ms`);
            })();
        }
        return this._buyFeaturePromise;
    }

    /** 背景 preload：只下載到 bundle cache，不 instantiate */
    async preloadAll(): Promise<void> {
        const bundle = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).getBundle();
        if (!bundle) return;
        const set = new Set<string>();
        for (const v of this.getViews()) {
            set.add(v.winAnimationPrefabPath || 'resources/prefabs/winAnimationView');
            set.add(v.jackpotPrefabPath || 'resources/prefabs/JackpotView');
            set.add(v.buyFeaturePrefabPath || 'resources/prefabs/buyFeaturePopup');
        }
        for (const path of set) {
            bundle.load(path, Prefab, (err) => {
                if (err) console.warn(`[Popup] preload failed: ${path}`, err);
                else console.log(`[Popup] preloaded: ${path}`);
            });
        }
    }

    /** 多 view 同步 show；任一 view dismiss 時觸發其他 view dismissExternal */
    private async showSynced<V extends DismissableView, A extends unknown[]>(loaded: Promise<V>, views: V[], invoke: (v: V, args: A) => Promise<void>, args: A): Promise<void> {
        await loaded;
        let dispatching = false;
        const dispatch = (originIdx: number) => {
            if (dispatching) return;
            dispatching = true;
            try {
                for (let j = 0; j < views.length; j++) {
                    if (j !== originIdx) views[j].dismissExternal();
                }
            } finally {
                dispatching = false;
            }
        };
        for (let i = 0; i < views.length; i++) {
            const idx = i;
            views[idx].onDismissing = () => dispatch(idx);
        }
        await Promise.all(views.map((v) => invoke(v, args)));
    }

    async showWinAnimation(...args: Parameters<WinAnimationView['show']>): Promise<void> {
        const view = await this.getWinAnimation();
        await view.show(...args);
    }

    showJackpotOnAll(...args: Parameters<JackpotView['show']>): Promise<void> {
        return this.showSynced(this.getJackpot(), this.jackpotViews, (v, a) => v.show(...a), args);
    }
}
